"""Exercise simplified care routes and controls in an isolated local browser."""
import base64,json,sys,time

def run(c,root,name):
 out=root/'tests/simplification-evidence';out.mkdir(exist_ok=True)
 c.sock.settimeout(300)
 c.call('Page.addScriptToEvaluateOnNewDocument',{'source':'localStorage.clear();'})
 entry=root/('DIST/index.html' if '--dist' in sys.argv else 'index.html')
 c.navigate(entry,timeout=60)
 for _ in range(400):
  if c.evaluate('!!window.AL?.game&&!!AL.CareUI&&!!AL.renderer'):break
  time.sleep(.05)
 else:raise RuntimeError('Simplified UI did not initialize')
 c.evaluate('AL.Startup.finish();AL.Save.unlock();AL.UI.close();AL.Store.close();AL.Shell.close();AL.game.settings.speed=0')
 model=c.evaluate((root/'tests/economy_update_checks.js').read_text(encoding='utf8'))
 checks=model['checks']
 def js(s):return c.evaluate('(()=>{'+s+'})()')
 def ck(label,expr):
  try:checks.append({'name':label,'pass':bool(c.evaluate('!!('+expr+')'))})
  except Exception as e:checks.append({'name':label,'pass':False,'error':str(e)})
 js("AL.game=AL.Core.act(economyFixture(),'buyFish',{species:'clown'});AL.game.tanks[0].fish[0].hunger=80;AL.game.inventory.salt=100;AL.UI.render()")
 ck('Six useful main navigation entries; no unfinished previews',"document.querySelectorAll('#navigation [data-page]').length===6&&!document.querySelector('#navigation [data-page=vip],#navigation [data-page=leaderboards]')")
 ck('Premium placeholder and development links removed from main aquarium',"!document.querySelector('.premium-preview,.bottom-bar a')")
 js("document.querySelector('#navigation [data-page=equipment]').click()")
 ck('Tank Care is the main equipment destination',"AL.Shell.active==='equipment'&&document.getElementById('primary-title').textContent==='Tank Care'")
 ck('Care tabs expose all existing routine operations',"['care','feeding','change','lighting','fragging','inventory'].every(id=>document.querySelector('[data-primary-tab='+id+']'))")
 ck('Window chooser contains exactly the same six destinations',"document.querySelectorAll('#window-switch option').length===6&&!document.querySelector('#window-switch [value=vip],#window-switch [value=leaderboards]')")
 js("document.querySelector('[data-primary-tab=feeding]').click();window.feedKind=AL.Data.species.clown.diet[0];AL.game.inventory[feedKind]=100;document.querySelector('[data-form=feed] select').value=feedKind;document.querySelector('[data-form=feed]').requestSubmit()")
 ck('Actual Feeding form consumes compatible inventory',"AL.game.inventory[feedKind]===99")
 ck('Feeding forecast retains game days and adds real hours',"AL.CareUI.forecast(24).includes('8.0 real hours')&&AL.CareUI.forecast(24).includes('24.0 game days')")
 js("document.querySelector('[data-primary-tab=lighting]').click();const f=document.querySelector('[data-form=lighting]');f.elements.mode.value='off';f.elements.hours.value='8';f.requestSubmit()")
 ck('Lighting form preserves working On/Off and schedule controls',"AL.Core.selected(AL.game).lightMode==='off'&&AL.Core.selected(AL.game).lightHours===8&&AL.Sim.light(AL.game,AL.Core.selected(AL.game))===0")
 js("document.querySelector('[data-primary-tab=change]').click();window.beforeChange=AL.game.credits;window.changePrice=AL.Update29.waterQuote(AL.Core.selected(AL.game),.25).water;document.querySelector('#primary-content [data-action=waterChange]').click()")
 ck('Actual Water Changes action uses existing exact quote',"AL.game.credits===beforeChange-changePrice")
 js("AL.Shell.open('aquariums','water')")
 ck('Water laboratory retains readings and routes changes through one care workflow',"document.querySelector('#primary-content [data-window=equipment][data-subtab=change]')&&!document.querySelector('#primary-content [data-action=waterChange]')&&document.getElementById('primary-content').textContent.includes('Calcium')")
 js("document.querySelector('#primary-content [data-window=equipment][data-subtab=change]').click()")
 ck('Laboratory water-change link opens the existing preview and confirmation',"AL.Shell.active==='equipment'&&AL.Shell.subtab==='change'&&document.querySelector('#primary-content [data-action=waterChange]')")
 js("document.querySelector('[data-primary-tab=care]').click();document.getElementById('care-category').value='filters';document.getElementById('care-category').dispatchEvent(new Event('change',{bubbles:true}))")
 ck('Installed equipment dropdown narrows the category without hiding storage',"document.querySelectorAll('#primary-content [data-action=inspectEquipment]').length===1&&document.querySelector('[data-primary-tab=inventory]')")
 ck('Equipment list keeps routine service and inspection with fewer actions',"!!document.querySelector('#primary-content [data-action=service]')&&!document.querySelector('#primary-content [data-action=moveEquipmentDialog]')")
 js("const e=AL.Core.selected(AL.game).equipment.find(e=>e.type==='filter');window.filterId=e.id;e.reliability.maintenance=40;document.querySelector('#primary-content [data-action=inspectEquipment]').click()")
 ck('Inspector retains transfers/removal and separate Maintenance/Replace Part',"['moveEquipmentDialog','uninstallEquipment','service'].every(a=>document.querySelector('#dialog-body [data-action='+a+']'))&&!!document.querySelector('#dialog-body [data-economy=parts]')")
 ck('Age and wear details are collapsed; service controls remain visible',"[...document.querySelectorAll('#dialog-body details')].some(d=>d.querySelector('summary').textContent.includes('Age, component wear')&&!d.open)&&!document.querySelector('#dialog-body [data-action=service]').closest('details')")
 js("window.serviceAge=AL.Core.selected(AL.game).equipment.find(e=>e.id===filterId).reliability.trackedHours;document.querySelector('#dialog-body [data-action=service]').click()")
 ck('Actual Maintenance preserves equipment identity and age',"AL.Core.selected(AL.game).equipment.find(e=>e.id===filterId).reliability.maintenance>95&&AL.Core.selected(AL.game).equipment.find(e=>e.id===filterId).reliability.trackedHours>=serviceAge")
 js("document.querySelector('#dialog-body [data-action=toggleEquipment]').click()")
 ck('Inspector on/off action updates the actual device and its label',"!AL.Core.selected(AL.game).equipment.find(e=>e.id===filterId).enabled&&document.querySelector('#dialog-body [data-action=toggleEquipment]').textContent==='Turn on'")
 js("document.querySelector('#dialog-body [data-action=toggleEquipment]').click()")
 ck('Inspector can turn the same device back on',"AL.Core.selected(AL.game).equipment.find(e=>e.id===filterId).enabled")
 js("document.querySelector('#dialog-body [data-action=moveEquipmentDialog]').click()")
 ck('Transfer destination workflow remains accessible from inspector',"!!document.getElementById('inventory-destination')")
 js("AL.UI.close();AL.InventoryUI.inspect({id:filterId});document.querySelector('#dialog-body [data-action=uninstallEquipment]').click()")
 ck('Equipment removal still requires explicit confirmation',"!!document.querySelector('#dialog-body [data-action=inventoryRemoveConfirmed]')&&AL.Core.selected(AL.game).equipment.some(e=>e.id===filterId)")
 js("AL.UI.close();AL.Shell.open('journal','achievements')")
 ck('Existing achievement links route into grouped Progress',"AL.Shell.subtab==='progress'&&document.querySelector('[data-progress-content=achievements]')&&document.getElementById('primary-content').textContent.includes('First-time milestones')")
 js("document.querySelector('[data-progress-section=quests]').click()")
 ck('Progress objectives retain optional saved care objectives',"document.querySelectorAll('#primary-content progress').length===13")
 js("AL.Shell.close();document.getElementById('level').click()")
 ck('Header Keeper Level shortcut reaches grouped Progress',"AL.Shell.subtab==='progress'&&!!document.querySelector('[data-progress-content=keeper]')")
 js("AL.Shell.open('aquariums','owned')")
 ck('Local asset comparison is available inside My Aquariums',"!!document.querySelector('.tank-comparison')&&document.querySelector('.tank-comparison').textContent.includes('AC')")
 js("AL.Shell.open('settings','preferences')")
 ck('Development review pages remain available in collapsed developer tools',"document.querySelector('.developer-tools a[href=\"art-review.html\"]')&&!document.querySelector('.developer-tools').open")
 js("AL.Shell.close();window.warningTime=AL.game.time;window.warningWallet=AL.game.credits;AL.CareUI.warnings(['First issue','Second issue','Third issue','Fourth issue','Fourth issue'],{reasons:[],danger:true})")
 ck('Warning summary lists three notes and retains every additional unique note',"document.querySelectorAll('#water-warning li').length===4&&document.querySelector('#water-warning details').textContent.includes('Fourth issue')&&AL.game.time===warningTime&&AL.game.credits===warningWallet")
 js("document.querySelector('#water-warning details').open=true;AL.CareUI.warnings(['First issue','Second issue','Third issue','Fourth issue'],{reasons:[],danger:true})")
 ck('Expanded warning details survive recurring updates',"!!document.querySelector('#water-warning details[open]')")
 js("document.getElementById('water-warning').textContent='';AL.CareUI.warnings(['First issue','Second issue','Third issue','Fourth issue'],{reasons:[],danger:true})")
 ck('Warnings recover after an empty-tank view clears its contents',"document.querySelectorAll('#water-warning li').length===4")
 js("AL.UI.updateVitals();AL.UI.save();window.simpleRaw=JSON.stringify(AL.game);window.simpleRestored=AL.Save.parse(simpleRaw)")
 ck('Simplification requires no new save schema or ownership migration',"simpleRestored.selectedTank===AL.game.selectedTank&&simpleRestored.tanks[0].fish[0].id===AL.game.tanks[0].fish[0].id&&simpleRestored.credits===AL.game.credits")
 for w,h in [(1920,1080),(1600,900),(1366,768),(390,844)]:
  c.call('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':False})
  for tab in ['care','feeding','change','lighting','inventory']:
   js(f"AL.Shell.open('equipment','{tab}')")
   ck(f'{w}x{h}: {tab} fits without horizontal overflow',"document.documentElement.scrollWidth<=innerWidth&&document.getElementById('primary-content').scrollWidth<=document.getElementById('primary-content').clientWidth+1")
  js("AL.Shell.open('equipment','care')");time.sleep(.1)
  (out/f'{name}-care-{w}.png').write_bytes(base64.b64decode(c.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})['data']))
 js("AL.Shell.close();const t=AL.Core.selected(AL.game),q=AL.AquariumSale.quote(AL.game,t.id);if(!q.ok)throw Error(q.reasons.join(';'));AL.game=AL.Core.act(AL.game,'sellEntireAquarium',{tankId:t.id,confirmed:true,fingerprint:q.fingerprint});AL.UI.render()")
 for window,tab in [('equipment','inventory'),('equipment','feeding'),('journal','keeper'),('aquariums','owned'),('settings','preferences')]:
  js(f"AL.Shell.open('{window}','{tab}')")
  ck(f'Zero-tank profile: {window}/{tab} retains a usable view',"document.getElementById('primary-content').textContent.length>0")
 errors=[e for e in c.events if e.get('method')=='Runtime.exceptionThrown']
 checks.append({'name':'No uncaught JavaScript exceptions','pass':not errors,'errors':errors})
 result={'entry':entry.relative_to(root).as_posix(),'passed':sum(bool(r['pass']) for r in checks),'failed':sum(not r['pass'] for r in checks),'checks':checks}
 (out/f'{name}-results.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf8')
 print(json.dumps({'entry':result['entry'],'passed':result['passed'],'failed':result['failed'],'failures':[r for r in checks if not r['pass']]},indent=2),flush=True)
 return int(result['failed']>0)
